import { useState, useEffect, useRef } from "react"; //My Sidebar
import { ProSidebar, Menu, MenuItem } from "react-pro-sidebar";
import { Box, IconButton, Typography, useTheme, Dialog, DialogTitle, DialogContent, TextField, Button } from "@mui/material";
import { Link, useNavigate } from "react-router-dom";
import "react-pro-sidebar/dist/css/styles.css";
import { tokens } from "../../theme";
import HomeOutlinedIcon from "@mui/icons-material/HomeOutlined";
import PeopleOutlinedIcon from "@mui/icons-material/PeopleOutlined";
import ContactsOutlinedIcon from "@mui/icons-material/ContactsOutlined";
import ReceiptOutlinedIcon from "@mui/icons-material/ReceiptOutlined";
import PersonOutlinedIcon from "@mui/icons-material/PersonOutlined";
import CalendarTodayOutlinedIcon from "@mui/icons-material/CalendarTodayOutlined";
import HelpOutlineOutlinedIcon from "@mui/icons-material/HelpOutlineOutlined";
// import BarChartOutlinedIcon from "@mui/icons-material/BarChartOutlined";
import PieChartOutlineOutlinedIcon from "@mui/icons-material/PieChartOutlineOutlined";
import TimelineOutlinedIcon from "@mui/icons-material/TimelineOutlined";
import MenuOutlinedIcon from "@mui/icons-material/MenuOutlined";
import MapOutlinedIcon from "@mui/icons-material/MapOutlined";
import PlayCircleOutlineIcon from "@mui/icons-material/PlayCircleOutline";

const Item = ({ title, to, icon, selected, setSelected }) => {
  const theme = useTheme();
  const colors = tokens(theme.palette.mode);
  return (
    <MenuItem
      active={selected === title}
      style={{
        color: colors.grey[100],
      }}
      onClick={() => setSelected(title)}
      icon={icon}
    >
      <Typography>{title}</Typography>
      <Link to={to} />
    </MenuItem>
  );
};

const Sidebar = () => {
  const theme = useTheme();
  const colors = tokens(theme.palette.mode);
  const navigate = useNavigate();
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [selected, setSelected] = useState("Dashboard");
  const [adminLoginOpen, setAdminLoginOpen] = useState(false);
  const [adminUsername, setAdminUsername] = useState("");
  const [adminPassword, setAdminPassword] = useState("");
  const sidebarRef = useRef(null);

  const handleAdminLogin = () => {
    console.log("Admin login attempt:", adminUsername);
    setAdminLoginOpen(false);
    setAdminUsername("");
    setAdminPassword("");
  };

  useEffect(() => {
    const updateSidebarHeight = () => {
      requestAnimationFrame(() => {
        const contentArea = document.querySelector('.content');
        const sidebarElement = sidebarRef.current?.querySelector('.pro-sidebar');
        
        if (contentArea && sidebarElement) {
          const contentHeight = Math.max(
            contentArea.offsetHeight,
            contentArea.scrollHeight,
            document.documentElement.clientHeight
          );
          sidebarElement.style.height = `${contentHeight}px`;
          const innerElement = sidebarElement.querySelector('.pro-sidebar-inner');
          if (innerElement) {
            innerElement.style.height = `${contentHeight}px`;
          }
        }
      });
    };

    // Initial update with delay to ensure DOM is ready
    const initialTimeout = setTimeout(updateSidebarHeight, 100);
    
    // Update on mount
    updateSidebarHeight();
    
    // Update on resize and zoom
    window.addEventListener('resize', updateSidebarHeight);
    window.addEventListener('orientationchange', updateSidebarHeight);
    
    // Use MutationObserver to watch for content changes
    const contentArea = document.querySelector('.content');
    let observer;
    if (contentArea) {
      observer = new MutationObserver(() => {
        updateSidebarHeight();
      });
      observer.observe(contentArea, { 
        childList: true, 
        subtree: true, 
        attributes: true,
        attributeFilter: ['style', 'class']
      });
    }
    
    // Fallback interval to catch any missed updates
    const intervalId = setInterval(updateSidebarHeight, 500);
    
    return () => {
      clearTimeout(initialTimeout);
      clearInterval(intervalId);
      window.removeEventListener('resize', updateSidebarHeight);
      window.removeEventListener('orientationchange', updateSidebarHeight);
      if (observer) {
        observer.disconnect();
      }
    };
  }, []);

  return (
    <Box
      ref={sidebarRef}
      sx={{
        "& .pro-sidebar-inner": {
          background: `${colors.primary[400]} !important`,
        },
        "& .pro-icon-wrapper": {
          backgroundColor: "transparent !important",
        },
        "& .pro-inner-item": {
          padding: "5px 35px 5px 20px !important",
        },
        "& .pro-inner-item:hover": {
          color: "#868dfb !important",
        },
        "& .pro-menu-item.active": {
          color: "#6870fa !important",
        },
      }}
    >
      <ProSidebar collapsed={isCollapsed}>
        <Menu iconShape="square">
          {/* LOGO AND MENU ICON */}
          <MenuItem
            onClick={() => setIsCollapsed(!isCollapsed)}
            icon={isCollapsed ? <MenuOutlinedIcon /> : undefined}
            style={{
              margin: "10px 0 20px 0",
              color: colors.grey[100],
            }}
          >
            {!isCollapsed && (
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="center"
                ml="15px"
              >
                <Typography 
                  variant="h3" 
                  color={colors.grey[100]}
                  sx={{ 
                    cursor: "pointer",
                    "&:hover": {
                      color: colors.orangeAccent[500]
                    }
                  }}
                  onClick={(e) => {
                    e.stopPropagation();
                    setAdminLoginOpen(true);
                  }}
                >
                  ADMIN
                </Typography>
                <IconButton onClick={() => setIsCollapsed(!isCollapsed)}>
                  <MenuOutlinedIcon />
                </IconButton>
              </Box>
            )}
          </MenuItem>

          {/* USER */}
          {!isCollapsed && (
            <Box mb="25px">
              <Box display="flex" justifyContent="center" alignItems="center">
                <img
                  alt="SkySentinel Home"
                  width="100px"
                  height="100px"
                  src={`../../logo512.png`}
                  style={{ cursor: "pointer", borderRadius: "38%" }}
                  onClick={() => navigate("/")}
                />
              </Box>

              <Box textAlign="center">
                <Typography
                  variant="h2"
                  color={colors.grey[100]}
                  fontWeight="bold"
                  sx={{ m: "10px 0 0 0" }}
                >
                  SkySentinel{" "}
                </Typography>
                <Typography variant="h5" color={colors.orangeAccent[500]}>
                  FrankenBits <br />
                  (SAM registered)
                </Typography>
              </Box>
            </Box>
          )}
          {/* MENU ITEMS */}
          <Box paddingLeft={isCollapsed ? undefined : "10%"}>
            <Item
              title="Dashboard"
              to="/dashboard"
              icon={<HomeOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="Product Demo"
              to="/product"
              icon={<PlayCircleOutlineIcon />}
              selected={selected}
              setSelected={setSelected}
            />

            <Typography
              variant="h6"
              color={colors.grey[300]}
              sx={{ m: "15px 0 5px 20px" }}
            >
              Data (Demo)
            </Typography>
            <Item
              title="Manage Team"
              to="/team"
              icon={<PeopleOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="Contacts Information"
              to="/contacts"
              icon={<ContactsOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="Invoices Balances"
              to="/invoices"
              icon={<ReceiptOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Typography
              variant="h6"
              color={colors.grey[300]}
              sx={{ m: "15px 0 5px 20px" }}
            >
              Pages (Demo)
            </Typography>
            <Item
              title="Profile Form"
              to="/form"
              icon={<PersonOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="Calendar"
              to="/calendar"
              icon={<CalendarTodayOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="FAQ Page"
              to="/faq"
              icon={<HelpOutlineOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Typography
              variant="h6"
              color={colors.grey[300]}
              sx={{ m: "15px 0 5px 20px" }}
            >
              Charts (Demo)
            </Typography>
            {/* <Item  // Broken source code form provider @nivo
              title="Bar Chart"
              to="/bar"
              icon={<BarChartOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            /> */}
            <Item
              title="Pie Chart"
              to="/pie"
              icon={<PieChartOutlineOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="Line Chart"
              to="/line"
              icon={<TimelineOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
            <Item
              title="Geography Chart"
              to="/geography"
              icon={<MapOutlinedIcon />}
              selected={selected}
              setSelected={setSelected}
            />
          </Box>
        </Menu>
      </ProSidebar>

      {/* Admin Login Dialog placeholder*/}
      <Dialog open={adminLoginOpen} onClose={() => setAdminLoginOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ backgroundColor: colors.primary[400], color: colors.grey[100] }}>
          <Typography variant="h4" fontWeight="600">
            Admin Login
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ backgroundColor: colors.primary[400], pt: 2 }}>
          <Box display="flex" flexDirection="column" gap="20px">
            <TextField
              fullWidth
              label="Admin Username"
              value={adminUsername}
              onChange={(e) => setAdminUsername(e.target.value)}
              sx={{
                "& .MuiOutlinedInput-root": {
                  "& fieldset": { borderColor: colors.grey[100] },
                  "&:hover fieldset": { borderColor: colors.orangeAccent[500] },
                  "&.Mui-focused fieldset": { borderColor: colors.orangeAccent[500] },
                },
                "& .MuiInputLabel-root": { color: colors.grey[100] },
                "& .MuiInputBase-input": { color: colors.grey[100] },
              }}
            />
            <TextField
              fullWidth
              type="password"
              label="Admin Password"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              sx={{
                "& .MuiOutlinedInput-root": {
                  "& fieldset": { borderColor: colors.grey[100] },
                  "&:hover fieldset": { borderColor: colors.orangeAccent[500] },
                  "&.Mui-focused fieldset": { borderColor: colors.orangeAccent[500] },
                },
                "& .MuiInputLabel-root": { color: colors.grey[100] },
                "& .MuiInputBase-input": { color: colors.grey[100] },
              }}
            />
            <Box display="flex" gap="10px" justifyContent="flex-end">
              <Button
                onClick={() => setAdminLoginOpen(false)}
                sx={{
                  color: colors.grey[100],
                  borderColor: colors.grey[100],
                  "&:hover": { borderColor: colors.grey[300] },
                }}
                variant="outlined"
              >
                Cancel
              </Button>
              <Button
                onClick={handleAdminLogin}
                sx={{
                  backgroundColor: colors.orangeAccent[500],
                  color: colors.grey[100],
                  "&:hover": { backgroundColor: colors.orangeAccent[600] },
                }}
                variant="contained"
              >
                Login
              </Button>
            </Box>
          </Box>
        </DialogContent>
      </Dialog>
    </Box>
  );
};

export default Sidebar;
